def process_and_find_min() -> int:
    N = int(input())
    beans = [list(map(int, input().split())) for _ in range(N)]

    # Group beans by color
    color_groups = {}
    for deliciousness, color in beans:
        if color not in color_groups:
            color_groups[color] = []
        color_groups[color].append(deliciousness)

    # Find the minimum deliciousness for each color group
    min_deliciousness_per_color = []
    for color in color_groups:
        min_deliciousness_per_color.append(min(color_groups[color]))

    # Find the maximum of these minimum deliciousness values
    max_possible_min_deliciousness = max(min_deliciousness_per_color)

    return max_possible_min_deliciousness
